sys_ui_action.script:
function printBadge() {

    var sysId = g_form.getUniqueValue();

    if (!sysId || sysId == '-1') {
        alert('Please save the record first before printing a badge.');
        return false;
    }

    var visitorName = g_form.getDisplayValue('u_visitor') || 'N/A';
    var vehiclePlate = g_form.getDisplayValue('u_vehicle') || 'N/A';
    var slotNumber = g_form.getDisplayValue('u_parking_slot') || 'N/A';
    var checkInTime = g_form.getDisplayValue('u_check_in_time') || 'N/A';

    var visitId = sysId.substring(0, 8).toUpperCase();

    var badgeHtml = '';

    badgeHtml += '<!DOCTYPE html>';
    badgeHtml += '<html>';
    badgeHtml += '<head>';
    badgeHtml += '<title>Visitor Badge</title>';

    badgeHtml += '<style>';
    badgeHtml += 'body { font-family: Arial; text-align: center; padding: 20px; }';
    badgeHtml += '.badge { border: 3px solid #2c3e50; border-radius: 10px; padding: 25px; width: 350px; margin: auto; }';
    badgeHtml += 'h2 { color: #2c3e50; margin: 0 0 5px 0; }';
    badgeHtml += '.visit-id { font-size: 12px; color: #888; margin-bottom: 10px; }';
    badgeHtml += 'hr { border: none; border-top: 1px solid #ccc; margin: 15px 0; }';
    badgeHtml += '.label { font-weight: bold; color: #555; font-size: 11px; display: block; text-transform: uppercase; }';
    badgeHtml += '.value { font-size: 16px; color: #000; margin-bottom: 12px; display: block; }';
    badgeHtml += '.footer { font-size: 11px; color: #888; margin-top: 20px; font-style: italic; }';
    badgeHtml += '</style>';

    badgeHtml += '</head>';
    badgeHtml += '<body>';

    badgeHtml += '<div class="badge">';

    badgeHtml += '<h2>VISITOR BADGE</h2>';
    badgeHtml += '<div class="visit-id">ID: ' + visitId + '</div>';

    badgeHtml += '<hr>';

    badgeHtml += '<span class="label">Visitor</span>';
    badgeHtml += '<span class="value">' + visitorName + '</span>';

    badgeHtml += '<span class="label">Vehicle</span>';
    badgeHtml += '<span class="value">' + vehiclePlate + '</span>';

    badgeHtml += '<span class="label">Parking Slot</span>';
    badgeHtml += '<span class="value">' + slotNumber + '</span>';

    badgeHtml += '<span class="label">Check-In Time</span>';
    badgeHtml += '<span class="value">' + checkInTime + '</span>';

    badgeHtml += '<hr>';

    badgeHtml += '<div class="footer">';
    badgeHtml += 'Please display this badge at all times while on premises.';
    badgeHtml += '</div>';

    badgeHtml += '</div>';

    badgeHtml += '</body>';
    badgeHtml += '</html>';

    // Create hidden iframe
    var iframe = document.createElement('iframe');

    iframe.style.position = 'fixed';
    iframe.style.left = '-10000px';
    iframe.style.top = '-10000px';
    iframe.style.width = '1px';
    iframe.style.height = '1px';
    iframe.style.border = '0';

    document.body.appendChild(iframe);

    var doc = iframe.contentWindow.document;

    doc.open();
    doc.write(badgeHtml);
    doc.close();

    setTimeout(function() {

        iframe.contentWindow.focus();
        iframe.contentWindow.print();

        setTimeout(function() {
            if (document.body.contains(iframe)) {
                document.body.removeChild(iframe);
            }
        }, 3000);

    }, 500);

    // Prevent UI Action from submitting/navigating the form
    return false;
}
